/**
 * Hand-written barrel re-exporting the generated contract client(s) under a namespace.
 * `ambassador.ts` is generated by `make bindings` (`stellar contract bindings typescript`)
 * and is overwritten on every run — never put hand-written code in it. This file is never
 * touched by that command; add one import/export line per new contract.
 */
import * as Ambassador from "./ambassador.js";
export { Ambassador };
export * from "@stellar/stellar-sdk";
export * as contract from "@stellar/stellar-sdk/contract";
export * as rpc from "@stellar/stellar-sdk/rpc";
